import{_ as n,o as e,c as s,a5 as i}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"Mini Codex v2 基础课开源：从零手写一个可审批、可验证、可复盘的 Coding Agent","description":"Mini Codex v2 基础课开源发布说明：用一套可运行的动手 Lab，理解 Coding Agent 的任务状态、权限边界、计划、diff、验证、trace 和 eval。","frontmatter":{"title":"Mini Codex v2 基础课开源：从零手写一个可审批、可验证、可复盘的 Coding Agent","description":"Mini Codex v2 基础课开源发布说明：用一套可运行的动手 Lab，理解 Coding Agent 的任务状态、权限边界、计划、diff、验证、trace 和 eval。","date":"2026-06-19T00:00:00.000Z","lang":"zh-CN","alternateZh":"/posts/ai-agent-coding-career/mini-codex-v2-open-source","alternateEn":"/posts/ai-agent-coding-career/mini-codex-v2-open-source-en","tags":["Mini Codex","Coding Agent","AI 应用工程师","Codex","开源课程"],"keywords":["Mini Codex","Coding Agent","Codex 教程","AI 应用工程师","开源课程"]},"headers":[],"relativePath":"posts/ai-agent-coding-career/mini-codex-v2-open-source.md","filePath":"posts/ai-agent-coding-career/mini-codex-v2-open-source.md","lastUpdated":1790163617000}'),p={name:"posts/ai-agent-coding-career/mini-codex-v2-open-source.md"};function t(o,a,l,d,c,r){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="mini-codex-v2-基础课开源" tabindex="-1">Mini Codex v2 基础课开源 <a class="header-anchor" href="#mini-codex-v2-基础课开源" aria-label="Permalink to &quot;Mini Codex v2 基础课开源&quot;">​</a></h1><p><a href="/blog/posts/ai-agent-coding-career/mini-codex-v2-open-source-en">English version</a></p><p>这套课不是提示词模板，也不是再做一个聊天套壳。</p><p>它的目标很具体：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>从一个空目录开始</span></span>
<span class="line"><span>-&gt; 做出一个本地 Mini Codex</span></span>
<span class="line"><span>-&gt; 让一次代码需求变成可追踪、可审批、可验证、可复盘的工程任务</span></span></code></pre></div><p>GitHub 仓库：</p><p><a href="https://github.com/herongdev/min-codex-hands-on-v2" target="_blank" rel="noreferrer">https://github.com/herongdev/min-codex-hands-on-v2</a></p><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><p>适合已经会基础前后端开发，并且正在使用 Codex、Cursor、Claude Code 这类 AI 编程工具的人。</p><p>你不需要先懂复杂 Agent 框架。更重要的是先理解这些工程问题：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为什么 Coding Agent 不是 Chatbot</span></span>
<span class="line"><span>为什么模型不能直接碰文件系统</span></span>
<span class="line"><span>为什么 prompt 不是安全边界</span></span>
<span class="line"><span>为什么改代码前要先生成计划和 diff</span></span>
<span class="line"><span>为什么没有 verify 就不能说任务完成</span></span>
<span class="line"><span>为什么 trace / eval 决定工具能不能持续变好</span></span></code></pre></div><h2 id="课程会做出什么" tabindex="-1">课程会做出什么 <a class="header-anchor" href="#课程会做出什么" aria-label="Permalink to &quot;课程会做出什么&quot;">​</a></h2><p>完成基础课后，你会得到一个最小但完整的 Mini Codex：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入一句代码修改需求</span></span>
<span class="line"><span>-&gt; 保存任务</span></span>
<span class="line"><span>-&gt; 给出计划</span></span>
<span class="line"><span>-&gt; 等你确认</span></span>
<span class="line"><span>-&gt; 修改文件</span></span>
<span class="line"><span>-&gt; 运行检查</span></span>
<span class="line"><span>-&gt; 保存过程</span></span>
<span class="line"><span>-&gt; 在桌面界面查看</span></span></code></pre></div><p>它不会复制官方 Codex 的全部能力。基础课只追求一件事：把最小闭环跑稳。</p><h2 id="课程目录" tabindex="-1">课程目录 <a class="header-anchor" href="#课程目录" aria-label="Permalink to &quot;课程目录&quot;">​</a></h2><p>公开基础课包含：</p><ol><li>Lab 00：环境准备和练习目录</li><li>Lab 01：保存第一条任务</li><li>Lab 02：让任务能停下来等你确认</li><li>Lab 03：Tool Registry 和权限边界</li><li>Lab 04：第一次真实代码修改</li><li>Lab 05：Trace、Replay 和 Eval</li><li>Lab 06：后端 API 和 SSE</li><li>Lab 07：桌面工作台</li><li>Lab 07b：UI 美化和设计系统</li><li>Lab 08：对照真实 Codex 能力边界</li><li>真实 Codex 功能升级包</li><li>练习案例</li><li>复盘台账</li></ol><h2 id="开源边界" tabindex="-1">开源边界 <a class="header-anchor" href="#开源边界" aria-label="Permalink to &quot;开源边界&quot;">​</a></h2><p>本次只开源基础课和公开升级方向。</p><p>v2 Advanced 进阶课独立维护，暂不随基础课仓库开源。展示页和 GitHub 仓库也不会公开进阶课目录、私有路径或商业课正文。</p><h2 id="为什么先开源基础课" tabindex="-1">为什么先开源基础课 <a class="header-anchor" href="#为什么先开源基础课" aria-label="Permalink to &quot;为什么先开源基础课&quot;">​</a></h2><p>AI 编程真正难的不是让模型生成代码，而是把生成代码这件事放进工程约束里：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有状态</span></span>
<span class="line"><span>有权限</span></span>
<span class="line"><span>有计划</span></span>
<span class="line"><span>有审查</span></span>
<span class="line"><span>有验证</span></span>
<span class="line"><span>有回放</span></span>
<span class="line"><span>有复盘</span></span></code></pre></div><p>先把这些基础能力亲手跑一遍，再讨论 RAG、Memory、MCP、Subagent、Git worktree、质量面板，才不容易把高级名词做成空架子。</p><p>下一步从仓库 README 开始：</p><p><a href="https://github.com/herongdev/min-codex-hands-on-v2" target="_blank" rel="noreferrer">进入 Mini Codex v2 基础课</a></p>`,27)])])}const b=n(p,[["render",t]]);export{g as __pageData,b as default};
